1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11		"syscall"
12	)
13	
14	// BuiltinVersionID identifies the built-in rule version, which reproduces
15	// the original fixed rules. It is always available, its parameters are
16	// queryable, and it cannot be overridden.
17	const BuiltinVersionID = "builtin"
18	
19	// ErrUnknownVersion reports a reference to a rule version that was never
20	// registered in the archive.
21	var ErrUnknownVersion = errors.New("unknown version")
22	
23	// ErrVersionConflict reports a re-registration of an existing version ID
24	// with different parameters.
25	var ErrVersionConflict = errors.New("version already registered with different parameters")
26	
27	// SandwichRule configures the sandwich rule: whether it runs and the
28	// severity of its conclusions.
29	type SandwichRule struct {
30		Enabled  bool `json:"enabled"`
31		Severity int  `json:"severity"`
32	}
33	
34	// DisplacementRule configures the displacement rule. A victim is flagged
35	// only when the previous swap's GasPrice strictly exceeds Multiplier times
36	// the victim's.
37	type DisplacementRule struct {
38		Enabled    bool `json:"enabled"`
39		Severity   int  `json:"severity"`
40		Multiplier int  `json:"multiplier"`
41	}
42	
43	// RuleSet is the complete declaration of both detection rules. Every
44	// version must declare both rules in full.
45	type RuleSet struct {
46		Sandwich     SandwichRule     `json:"sandwich"`
47		Displacement DisplacementRule `json:"displacement"`
48	}
49	
50	// RuleVersion is a named, immutable set of rule parameters.
51	type RuleVersion struct {
52		ID    string  `json:"id"`
53		Rules RuleSet `json:"rules"`
54	}
55	
56	// BuiltinVersion returns the version representing the original fixed
57	// rules: sandwich severity 3, displacement severity 2 with multiplier 2.
58	func BuiltinVersion() RuleVersion {
59		return RuleVersion{
60			ID: BuiltinVersionID,
61			Rules: RuleSet{
62				Sandwich:     SandwichRule{Enabled: true, Severity: 3},
63				Displacement: DisplacementRule{Enabled: true, Severity: 2, Multiplier: 2},
64			},
65		}
66	}
67	
68	// toggleSpec and displacementSpec mirror the registration JSON. Pointers
69	// distinguish a missing field from an explicit zero value, and the decoder
70	// rejects unknown fields (including unknown rule names).
71	type toggleSpec struct {
72		Enabled  *bool `json:"enabled"`
73		Severity *int  `json:"severity"`
74	}
75	
76	type displacementSpec struct {
77		Enabled    *bool `json:"enabled"`
78		Severity   *int  `json:"severity"`
79		Multiplier *int  `json:"multiplier"`
80	}
81	
82	type versionSpec struct {
83		ID    *string `json:"id"`
84		Rules *struct {
85			Sandwich     *toggleSpec       `json:"sandwich"`
86			Displacement *displacementSpec `json:"displacement"`
87		} `json:"rules"`
88	}
89	
90	func parseEnabled(name string, v *bool) (bool, error) {
91		if v == nil {
92			return false, fmt.Errorf("rules.%s.enabled is required (boolean)", name)
93		}
94		return *v, nil
95	}
96	
97	func parseSeverity(name string, v *int) (int, error) {
98		if v == nil {
99			return 0, fmt.Errorf("rules.%s.severity is required (integer 1-5)", name)
100		}
101		if *v < 1 || *v > 5 {
102			return 0, fmt.Errorf("rules.%s.severity must be between 1 and 5, got %d", name, *v)
103		}
104		return *v, nil
105	}
106	
107	// ErrDuplicateField reports a JSON object in a registration spec that
108	// names the same field twice. Field names are compared the way JSON
109	// decoding matches struct fields, so two spellings that differ only in
110	// case (for example "severity" and "Severity") are also duplicates.
111	var ErrDuplicateField = errors.New("duplicate field in version spec")
112	
113	// ErrTrailingData reports non-whitespace content after the single JSON
114	// object that makes up a registration spec: a second object, another
115	// JSON value, an unmatched bracket or any other character.
116	var ErrTrailingData = errors.New("unexpected trailing data after version spec")
117	
118	// versionScanPolicy validates the shape of a rule version document with
119	// the shared scanner while keeping version-spec wording and sentinel
120	// errors.
121	var versionScanPolicy = specPolicy{
122		topObject:          "version spec",
123		known:              versionFields,
124		nested:             versionNestedTables,
125		rejectExactUnknown: true,
126		firstTokenError: func(err error) error {
127			if errors.Is(err, io.EOF) {
128				return errors.New("version spec must be a JSON object, got empty input")
129			}
130			return fmt.Errorf("invalid version spec: %w", err)
131		},
132		nonObject: func(tok json.Token) error {
133			if tok == nil {
134				return errors.New("version spec must be a JSON object, got null")
135			}
136			if d, ok := tok.(json.Delim); ok && d == '[' {
137				return errors.New("version spec must be a single JSON object, got array")
138			}
139			return fmt.Errorf("version spec must be a single JSON object, got %s", jsonTokenName(tok))
140		},
141		wrap: func(err error) error {
142			return fmt.Errorf("invalid version spec: %w", err)
143		},
144		duplicate: func(obj, field, first, _ string) error {
145			return fmt.Errorf("%w: %s field %q (also written %q)", ErrDuplicateField, obj, field, first)
146		},
147		trailing: versionTrailingData,
148	}
149	
150	// validateSpecStructure proves raw contains exactly one JSON object with
151	// no repeated fields anywhere in it, and nothing but whitespace around
152	// it. Keys are matched case-insensitively against the known fields of
153	// the version, rules, sandwich and displacement objects, preserving the
154	// decoder's case-compatible field matching: "SEVERITY" and "severity"
155	// point at the same field and cannot both appear. Escaped key spellings
156	// are decoded before comparison, so "severity" cannot evade it.
157	func validateSpecStructure(raw []byte) error {
158		return scanJSONObject(raw, versionScanPolicy)
159	}
160	
161	// versionTrailingData names the first non-whitespace byte after the
162	// closed object, so an unmatched '}' or ']' is reported directly rather
163	// than as a syntax error; only whitespace may follow the object.
164	func versionTrailingData(raw []byte, offset int) error {
165		rest := bytes.TrimLeft(raw[offset:], " \t\n\r")
166		if len(rest) > 0 {
167			return fmt.Errorf("%w: %s after closing object", ErrTrailingData, trailingTokenName(rest[0]))
168		}
169		return nil
170	}
171	
172	var (
173		versionFields       = fieldTable("id", "rules")
174		rulesFields         = fieldTable("sandwich", "displacement")
175		sandwichFields      = fieldTable("enabled", "severity")
176		displacementFields  = fieldTable("enabled", "severity", "multiplier")
177		versionNestedTables = map[string]nestedObjectSpec{
178			"rules":        {rulesFields, "rules object"},
179			"sandwich":     {sandwichFields, "rules.sandwich"},
180			"displacement": {displacementFields, "rules.displacement"},
181		}
182	)
183	
184	// ParseRuleVersion validates a registration document. It must contain
185	// exactly one complete JSON object (leading and trailing whitespace
186	// allowed): a second object or value, an unmatched bracket or any other
187	// trailing character fails, and empty input, arrays and null are not
188	// specs. Duplicate fields are rejected at the top level, in rules and in
189	// each rule's parameters, including case-only variants of the same known
190	// field. Missing fields, wrong types, out-of-range values and unknown
191	// rules or fields all fail with a reason.
192	func ParseRuleVersion(raw []byte) (RuleVersion, error) {
193		if err := validateSpecStructure(raw); err != nil {
194			return RuleVersion{}, err
195		}
196		var spec versionSpec
197		dec := json.NewDecoder(bytes.NewReader(raw))
198		dec.DisallowUnknownFields()
199		if err := dec.Decode(&spec); err != nil {
200			return RuleVersion{}, fmt.Errorf("invalid version spec: %w", err)
201		}
202		if spec.ID == nil || *spec.ID == "" {
203			return RuleVersion{}, errors.New("id must be a non-empty string")
204		}
205		if spec.Rules == nil {
206			return RuleVersion{}, errors.New("rules must declare sandwich and displacement")
207		}
208		if spec.Rules.Sandwich == nil {
209			return RuleVersion{}, errors.New("rules.sandwich is required")
210		}
211		if spec.Rules.Displacement == nil {
212			return RuleVersion{}, errors.New("rules.displacement is required")
213		}
214		sandwichOn, err := parseEnabled("sandwich", spec.Rules.Sandwich.Enabled)
215		if err != nil {
216			return RuleVersion{}, err
217		}
218		sandwichSev, err := parseSeverity("sandwich", spec.Rules.Sandwich.Severity)
219		if err != nil {
220			return RuleVersion{}, err
221		}
222		dispOn, err := parseEnabled("displacement", spec.Rules.Displacement.Enabled)
223		if err != nil {
224			return RuleVersion{}, err
225		}
226		dispSev, err := parseSeverity("displacement", spec.Rules.Displacement.Severity)
227		if err != nil {
228			return RuleVersion{}, err
229		}
230		mult := spec.Rules.Displacement.Multiplier
231		if mult == nil {
232			return RuleVersion{}, errors.New("rules.displacement.multiplier is required (integer 2-100)")
233		}
234		if *mult < 2 || *mult > 100 {
235			return RuleVersion{}, fmt.Errorf("rules.displacement.multiplier must be between 2 and 100, got %d", *mult)
236		}
237		return RuleVersion{
238			ID: *spec.ID,
239			Rules: RuleSet{
240				Sandwich:     SandwichRule{Enabled: sandwichOn, Severity: sandwichSev},
241				Displacement: DisplacementRule{Enabled: dispOn, Severity: dispSev, Multiplier: *mult},
242			},
243		}, nil
244	}
245	
246	// findVersion resolves id against the built-in version and the archive's
247	// registered versions.
248	func findVersion(data archiveData, id string) (RuleVersion, error) {
249		if id == BuiltinVersionID {
250			return BuiltinVersion(), nil
251		}
252		for _, v := range data.Versions {
253			if v.ID == id {
254				return v, nil
255			}
256		}
257		return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
258	}
259	
260	// enabledVersion resolves the archive's currently enabled version. Archives
261	// written before rule versions existed have no marker and run the built-in
262	// rules.
263	func (d archiveData) enabledVersion() (RuleVersion, error) {
264		if d.EnabledVersion == "" {
265			return BuiltinVersion(), nil
266		}
267		return findVersion(d, d.EnabledVersion)
268	}
269	
270	// RegisterVersion validates raw as a rule version spec and stores it in the
271	// archive at dir. Re-registering the same ID with identical parameters
272	// succeeds without adding a version (created is false); the same ID with
273	// different parameters is rejected. The built-in version ID is reserved.
274	// Any failure leaves the archive untouched.
275	func RegisterVersion(dir string, raw []byte) (v RuleVersion, created bool, err error) {
276		v, err = ParseRuleVersion(raw)
277		if err != nil {
278			return RuleVersion{}, false, err
279		}
280		if v.ID == BuiltinVersionID {
281			return RuleVersion{}, false, fmt.Errorf("version id %q is reserved for the built-in rules", BuiltinVersionID)
282		}
283		if err := os.MkdirAll(dir, 0o755); err != nil {
284			return RuleVersion{}, false, err
285		}
286		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
287		if err != nil {
288			return RuleVersion{}, false, err
289		}
290		defer lock.Close()
291	
292		data, err := readArchive(dir)
293		if err != nil {
294			return RuleVersion{}, false, err
295		}
296		for _, existing := range data.Versions {
297			if existing.ID == v.ID {
298				if existing.Rules == v.Rules {
299					return existing, false, nil
300				}
301				return RuleVersion{}, false, fmt.Errorf("%w: %s", ErrVersionConflict, v.ID)
302			}
303		}
304		data.Versions = append(data.Versions, v)
305		if err := writeArchiveAtomic(dir, data); err != nil {
306			return RuleVersion{}, false, err
307		}
308		return v, true, nil
309	}
310	
311	// EnableVersion makes id the archive's active version for later replays.
312	// Enabling an unknown version fails and leaves the current enabled version
313	// unchanged.
314	func EnableVersion(dir, id string) (RuleVersion, error) {
315		if id == "" {
316			return RuleVersion{}, errors.New("version id must not be empty")
317		}
318		if err := os.MkdirAll(dir, 0o755); err != nil {
319			return RuleVersion{}, err
320		}
321		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
322		if err != nil {
323			return RuleVersion{}, err
324		}
325		defer lock.Close()
326	
327		data, err := readArchive(dir)
328		if err != nil {
329			return RuleVersion{}, err
330		}
331		v, err := findVersion(data, id)
332		if err != nil {
333			return RuleVersion{}, err
334		}
335		if data.EnabledVersion == id {
336			return v, nil
337		}
338		data.EnabledVersion = id
339		if err := writeArchiveAtomic(dir, data); err != nil {
340			return RuleVersion{}, err
341		}
342		return v, nil
343	}
344	
345	// ListVersions returns the built-in version plus every version registered
346	// in the archive, along with the currently enabled version ID.
347	func ListVersions(dir string) (versions []RuleVersion, enabled string, err error) {
348		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
349			return []RuleVersion{BuiltinVersion()}, BuiltinVersionID, nil
350		}
351		lock, err := lockArchive(dir, syscall.LOCK_SH)
352		if err != nil {
353			return nil, "", err
354		}
355		defer lock.Close()
356	
357		data, err := readArchive(dir)
358		if err != nil {
359			return nil, "", err
360		}
361		versions = append([]RuleVersion{BuiltinVersion()}, data.Versions...)
362		enabled = data.EnabledVersion
363		if enabled == "" {
364			enabled = BuiltinVersionID
365		}
366		return versions, enabled, nil
367	}
368	
369	// GetVersion returns one version's full parameters by ID.
370	func GetVersion(dir, id string) (RuleVersion, error) {
371		if id == BuiltinVersionID {
372			return BuiltinVersion(), nil
373		}
374		if _, serr := os.Stat(dir); errors.Is(serr, os.ErrNotExist) {
375			return RuleVersion{}, fmt.Errorf("%w: %s", ErrUnknownVersion, id)
376		}
377		lock, err := lockArchive(dir, syscall.LOCK_SH)
378		if err != nil {
379			return RuleVersion{}, err
380		}
381		defer lock.Close()
382	
383		data, err := readArchive(dir)
384		if err != nil {
385			return RuleVersion{}, err
386		}
387		return findVersion(data, id)
388	}
389	
390	// FindingChange pairs the archived and compared conclusions for one
391	// transaction whose kind or severity differs between the two versions.
392	type FindingChange struct {
393		TxHash   string        `json:"txHash"`
394		Original ReportFinding `json:"original"`
395		Compared ReportFinding `json:"compared"`
396	}
397	
398	// CompareResult is the outcome of re-judging one archived block under a
399	// different rule version. It carries both versions' parameters, both full
400	// conclusion sets, the raw swap evidence, and the per-transaction diff.
401	type CompareResult struct {
402		ChainID          string          `json:"chainId"`
403		BlockHash        string          `json:"blockHash"`
404		BlockNumber      int64           `json:"blockNumber"`
405		OriginalVersion  RuleVersion     `json:"originalVersion"`
406		ComparedVersion  RuleVersion     `json:"comparedVersion"`
407		OriginalFindings []ReportFinding `json:"originalFindings"`
408		ComparedFindings []ReportFinding `json:"comparedFindings"`
409		Swaps            []Swap          `json:"swaps"`
410		Added            []ReportFinding `json:"added"`
411		Removed          []ReportFinding `json:"removed"`
412		Changed          []FindingChange `json:"changed"`
413	}
414	
415	// Compare re-runs detection for one archived block under the given
416	// registered version and diffs the conclusions against the archived
417	// report. It only reads the archive: the original input file is not
418	// needed, and neither the archived report nor the enabled version is
419	// modified.
420	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
421		if _, err := os.Stat(dir); err != nil {
422			if errors.Is(err, os.ErrNotExist) {
423				return CompareResult{}, ErrUnknownBlock
424			}
425			return CompareResult{}, err
426		}
427		lock, err := lockArchive(dir, syscall.LOCK_SH)
428		if err != nil {
429			return CompareResult{}, err
430		}
431		defer lock.Close()
432	
433		data, err := readArchive(dir)
434		if err != nil {
435			return CompareResult{}, err
436		}
437		var rec *record
438		for i := range data.Records {
439			if data.Records[i].ChainID == chainID && data.Records[i].BlockHash == blockHash {
440				rec = &data.Records[i]
441				break
442			}
443		}
444		if rec == nil {
445			return CompareResult{}, ErrUnknownBlock
446		}
447		compared, err := findVersion(data, versionID)
448		if err != nil {
449			return CompareResult{}, err
450		}
451	
452		original := rec.Findings
453		if original == nil {
454			original = []ReportFinding{}
455		}
456		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
457		swaps := rec.Swaps
458		if swaps == nil {
459			swaps = []Swap{}
460		}
461	
462		origByTx := make(map[string]ReportFinding, len(original))
463		for _, f := range original {
464			origByTx[f.TxHash] = f
465		}
466		compByTx := make(map[string]ReportFinding, len(rejudged))
467		for _, f := range rejudged {
468			compByTx[f.TxHash] = f
469		}
470		added := []ReportFinding{}
471		removed := []ReportFinding{}
472		changed := []FindingChange{}
473		for _, f := range rejudged {
474			if o, ok := origByTx[f.TxHash]; ok {
475				// A transaction present on both sides with a different kind or
476				// severity is a change, never an add plus a remove.
477				if o.Kind != f.Kind || o.Severity != f.Severity {
478					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
479				}
480			} else {
481				added = append(added, f)
482			}
483		}
484		for _, f := range original {
485			if _, ok := compByTx[f.TxHash]; !ok {
486				removed = append(removed, f)
487			}
488		}
489		byTx := func(fs []ReportFinding) {
490			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
491		}
492		byTx(added)
493		byTx(removed)
494		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
495	
496		return CompareResult{
497			ChainID:          rec.ChainID,
498			BlockHash:        rec.BlockHash,
499			BlockNumber:      rec.BlockNumber,
500			OriginalVersion:  rec.ruleVersion(),
501			ComparedVersion:  compared,
502			OriginalFindings: original,
503			ComparedFindings: rejudged,
504			Swaps:            swaps,
505			Added:            added,
506			Removed:          removed,
507			Changed:          changed,
508		}, nil
509	}
