88			if !ok {
89				return p.wrap(fmt.Errorf("object key is %s, want string", jsonTokenName(keyTok)))
90			}
91			target, knownKey := known[strings.ToLower(key)]
92			if p.rejectExactUnknown {
93				// An exact repeat of a decoded key name (known or unknown) is a
94				// duplicate; escapes are decoded first, so "id" == "id".
95				if first, dup := spellings[key]; dup {
96					return p.duplicate(obj, key, first, key)
97				}
98				spellings[key] = key
99			}
100			if knownKey {
101				// A case-only spelling of the same known field is the same
102				// field: "Severity" and "severity" cannot share one object.
103				if first, dup := seen[target]; dup {
104					return p.duplicate(obj, target, first, key)
105				}
106				seen[target] = key
107			}
108			start, err := dec.Token()
109			if err != nil {
110				return p.wrap(err)
111			}
112			if d, isDelim := start.(json.Delim); isDelim {
113				switch d {
114				case '{':
115					nested, hasShape := p.nested[target]
116					if !knownKey || !hasShape {
117						if err := skipContainer(dec, p); err != nil {
118							return err
119						}
120						continue
121					}
122					if err := scanObject(dec, p, nested.fields, nested.label); err != nil {
123						return err
124					}
125				case '[':
126					if err := skipContainer(dec, p); err != nil {
127						return err
128					}
129				}
130				continue
131			}
132		}
133		closeTok, err := dec.Token()
134		if err != nil {
135			return p.wrap(err)
136		}
137		if closeTok != json.Delim('}') {
138			return p.wrap(fmt.Errorf("expected closing brace, got %s", jsonTokenName(closeTok)))
139		}
140		return nil
141	}
142	
143	// skipContainer consumes the remainder of one object or array whose
144	// opening delimiter has already been read, balancing nested brackets. The
145	// scanner itself rejects mismatched brackets, so only depth bookkeeping is
146	// needed here.
147	func skipContainer(dec *json.Decoder, p specPolicy) error {
148		depth := 1
149		for depth > 0 {
150			tok, err := dec.Token()
151			if err != nil {
152				return p.wrap(err)
153			}
154			if d, ok := tok.(json.Delim); ok {
155				switch d {
156				case '{', '[':
157					depth++
158				case '}', ']':
159					depth--
160				}
161			}
162		}
163		return nil
164	}
