		}
		start, err := dec.Token()
		if err != nil {
			return p.wrap(err)
		}
		if d, isDelim := start.(json.Delim); isDelim {
			switch d {
			case '{':
				nested, hasShape := p.nested[target]
				if !knownKey || !hasShape {
