cat > /tmp/foldcheck_test.go <<'EOF'
package mevwatch

import (
	"errors"
	"strings"
	"testing"
)

func TestFoldCheckManual(t *testing.T) {
	full := `"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}`
	cases := []struct {
		name, spec, obj, field string
	}{
		{"long-s severity", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3,"ſeverity":5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`, "rules.sandwich", "severity"},
		{"long-s rules", `{"id":"v","rules":{` + full + `},"ruleſ":{` + full + `}}`, "version spec", "rules"},
		{"long-s sandwich", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"ſandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`, "rules object", "sandwich"},
		{"escaped long-s", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`, "", ""},
		{"split long-s sandwich", `{"id":"v","rules":{"sandwich":{"enabled":true},"ſandwich":{"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`, "rules object", "sandwich"},
	}
	for _, tc := range cases {
		_, err := ParseRuleVersion([]byte(tc.spec))
		if tc.obj == "" {
			if err != nil {
				t.Fatalf("%s: valid spec rejected: %v", tc.name, err)
			}
			continue
		}
		if !errors.Is(err, ErrDuplicateField) {
			t.Fatalf("%s: got %v, want ErrDuplicateField", tc.name, err)
		}
		if !strings.Contains(err.Error(), tc.obj) || !strings.Contains(err.Error(), `"`+tc.field+`"`) {
			t.Fatalf("%s: error %q missing object %q or field %q", tc.name, err, tc.obj, tc.field)
		}
	}
	// Escaped ſ must behave like literal ſ.
	esc := `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3,"ſeverity":5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
	if _, err := ParseRuleVersion([]byte(esc)); !errors.Is(err, ErrDuplicateField) {
		t.Fatalf("escaped long-s: got %v, want ErrDuplicateField", err)
	}
	// A single ſ severity is legal and stores the value.
	v, err := ParseRuleVersion([]byte(`{"id":"v","rules":{"sandwich":{"enabled":true,"ſeverity":5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`))
	if err != nil || v.Rules.Sandwich.Severity != 5 {
		t.Fatalf("single long-s severity: v=%+v err=%v", v, err)
	}
	// Unknown lookalike is still an unknown field, not a legal alias.
	if _, err := ParseRuleVersion([]byte(`{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3,"ſeveritie":5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`)); err == nil || errors.Is(err, ErrDuplicateField) {
		t.Fatalf("unknown lookalike: got %v", err)
	}
}
EOF
